using System.Collections.Generic;
using System.Net.Http;
using System.Threading.Tasks;

public sealed class ThumbnailWarmer
{
    private readonly HttpClient _http;

    public ThumbnailWarmer(HttpClient http) => _http = http;

    // Requests every thumbnail concurrently so the CDN caches them and returns how many succeeded.
    // Callers pass at most 50 URLs; network failures propagate to the caller.
    public async Task<int> WarmAsync(IReadOnlyList<string> urls)
    {
        var requests = new List<Task<bool>>(urls.Count);
        for (int i = 0; i < urls.Count; i++)
        {
            requests.Add(Task.Run(() => FetchAsync(urls[i])));
        }

        bool[] results = await Task.WhenAll(requests);
        int warmed = 0;
        foreach (bool ok in results)
        {
            if (ok) warmed++;
        }
        return warmed;
    }

    private async Task<bool> FetchAsync(string url)
    {
        using HttpResponseMessage response = await _http.GetAsync(url, HttpCompletionOption.ResponseHeadersRead);
        return response.IsSuccessStatusCode;
    }
}

