using System;
using System.Threading.Tasks;
using System.Windows.Forms;

public sealed record Customer(int Id, string Name);
public sealed class CustomerApiException(string message) : Exception(message);

// Faults with CustomerApiException when the customer cannot be loaded.
public interface ICustomerApi { Task<Customer> GetCustomerAsync(int id); }

public sealed class CustomerForm : Form
{
    private readonly ICustomerApi _api;
    private readonly TextBox _idBox = new() { Dock = DockStyle.Top };
    private readonly Button _loadButton = new() { Text = "Load", Dock = DockStyle.Top };
    private readonly Label _nameLabel = new() { Dock = DockStyle.Top };

    public CustomerForm(ICustomerApi api)
    {
        _api = api;
        Controls.AddRange(new Control[] { _nameLabel, _loadButton, _idBox });
        _loadButton.Click += OnLoadClicked;
    }

    private void OnLoadClicked(object? sender, EventArgs e)
    {
        if (!int.TryParse(_idBox.Text, out int id)) { _nameLabel.Text = "Invalid id"; return; }

        _loadButton.Enabled = false;
        try
        {
            Customer customer = _api.GetCustomerAsync(id).Result;
            _nameLabel.Text = customer.Name;
        }
        catch (CustomerApiException ex)
        {
            _nameLabel.Text = "Load failed: " + ex.Message;
        }
        finally
        {
            _loadButton.Enabled = true;
        }
    }
}

