using System.Collections.Generic;
using System.Linq;

public sealed record Timesheet(int CustomerId, decimal BillableHours, decimal HourlyRate);
public sealed record Invoice(int CustomerId, decimal Amount);
public interface IInvoiceRepository { Invoice Insert(Invoice invoice); }
public interface IAuditLog { void Record(string message); }

public sealed class InvoiceBatchCreator
{
    private readonly IInvoiceRepository _repository;
    private readonly IAuditLog _audit;

    public InvoiceBatchCreator(IInvoiceRepository repository, IAuditLog audit)
    {
        _repository = repository;
        _audit = audit;
    }

    // Inserts one invoice per billable timesheet and returns the stored invoices.
    // Inserts are independent: a failure stops the batch and earlier invoices stay stored.
    public IReadOnlyList<Invoice> CreateInvoices(IEnumerable<Timesheet> timesheets)
    {
        IEnumerable<Invoice> created = timesheets
            .Where(t => t.BillableHours > 0)
            .Select(t => _repository.Insert(new Invoice(t.CustomerId, t.BillableHours * t.HourlyRate)));

        _audit.Record($"Created {created.Count()} invoices");
        return created.ToList();
    }
}

