using System;
using System.Collections.Generic;

public static class FeatureFlagParser
{
    // Parses "NAME=on|off" lines. Names are ASCII identifiers, matched case-insensitively:
    // they are normalized to upper case and callers look flags up as e.g. "DARK_MODE".
    // Blank lines and '#' comments are skipped; a later line overrides an earlier one.
    public static Dictionary<string, bool> Parse(IEnumerable<string> lines)
    {
        var flags = new Dictionary<string, bool>(StringComparer.Ordinal);
        foreach (string raw in lines)
        {
            string line = raw.Trim();
            if (line.Length == 0 || line.StartsWith('#')) continue;

            int eq = line.IndexOf('=');
            if (eq <= 0) throw new FormatException($"Invalid flag line: {line}");

            string name = line.Substring(0, eq).Trim().ToUpper();
            string value = line.Substring(eq + 1).Trim();
            flags[name] = value.Equals("on", StringComparison.OrdinalIgnoreCase) ? true
                : value.Equals("off", StringComparison.OrdinalIgnoreCase) ? false
                : throw new FormatException($"Invalid value for {name}: {value}");
        }
        return flags;
    }
}

