using System;

public sealed record Subscription(string CustomerId, DateTime StartsAtUtc, DateTime EndsAtUtc, bool Cancelled);

public enum AccessLevel { None, ReadOnly, Full }

public sealed class SubscriptionGate
{
    private static readonly TimeSpan GracePeriod = TimeSpan.FromDays(3);

    // Subscription timestamps come from the billing database in UTC.
    // Paid period: full access. Grace period after it ends: read-only. Cancelled: no access.
    public AccessLevel Evaluate(Subscription subscription)
    {
        if (subscription.Cancelled) return AccessLevel.None;

        DateTime now = DateTime.Now;
        if (now < subscription.StartsAtUtc) return AccessLevel.None;
        if (now <= subscription.EndsAtUtc) return AccessLevel.Full;
        if (now <= subscription.EndsAtUtc + GracePeriod) return AccessLevel.ReadOnly;
        return AccessLevel.None;
    }
}

