using System;
using System.Collections.Generic;

public sealed class PriceChangedEventArgs : EventArgs
{
    public PriceChangedEventArgs(string symbol, decimal price) { Symbol = symbol; Price = price; }
    public string Symbol { get; }
    public decimal Price { get; }
}

// Application-wide singleton; raises PriceChanged on the UI thread.
public sealed class PriceTicker
{
    public event EventHandler<PriceChangedEventArgs>? PriceChanged;
    public void Publish(string symbol, decimal price) => PriceChanged?.Invoke(this, new PriceChangedEventArgs(symbol, price));
}

// One instance per open chart window; disposed when the window closes.
public sealed class ChartViewModel : IDisposable
{
    private readonly PriceTicker _ticker;
    private readonly string _symbol;
    private readonly List<decimal> _history = new();

    public ChartViewModel(PriceTicker ticker, string symbol)
    {
        _ticker = ticker;
        _symbol = symbol;
        _ticker.PriceChanged += OnPriceChanged;
    }

    public IReadOnlyList<decimal> History => _history;

    private void OnPriceChanged(object? sender, PriceChangedEventArgs e)
    {
        if (e.Symbol == _symbol) _history.Add(e.Price);
    }

    public void Dispose()
    {
        _history.Clear();
    }
}

