using System.IO;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

public sealed class ReportOptions
{
    public string Directory { get; set; } = "";
}

// Serves generated PDF reports, which are stored flat (no subfolders) in the configured report directory.
[ApiController]
[Authorize]
[Route("api/reports")]
public sealed class ReportDownloadController : ControllerBase
{
    private readonly string _reportRoot;

    public ReportDownloadController(ReportOptions options) =>
        _reportRoot = Path.TrimEndingDirectorySeparator(Path.GetFullPath(options.Directory));

    [HttpGet("download")]
    public IActionResult Download([FromQuery] string name)
    {
        string path = Path.Combine(_reportRoot, name);
        if (!System.IO.File.Exists(path)) return NotFound();
        return PhysicalFile(path, "application/pdf", Path.GetFileName(path));
    }
}

