using System;
using System.Collections.Generic;
using System.Linq;

public sealed record Page<T>(IReadOnlyList<T> Items, int PageNumber, int TotalPages);

public static class Paginator
{
    public const int MaxPageSize = 500;

    // pageNumber is 1-based: page 1 holds the first pageSize items.
    // Pages past the end are returned empty.
    public static Page<T> GetPage<T>(IReadOnlyList<T> source, int pageNumber, int pageSize)
    {
        if (pageNumber < 1) throw new ArgumentOutOfRangeException(nameof(pageNumber));
        if (pageSize < 1 || pageSize > MaxPageSize) throw new ArgumentOutOfRangeException(nameof(pageSize));

        int totalPages = (source.Count + pageSize - 1) / pageSize;
        if (pageNumber > totalPages) return new Page<T>(Array.Empty<T>(), pageNumber, totalPages);

        List<T> items = source.Skip(pageNumber * pageSize).Take(pageSize).ToList();
        return new Page<T>(items, pageNumber, totalPages);
    }
}

